#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long k;
    cin >> n >> k;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    vector<int> end(n + 1, 0);
    int flip = 0;
    long long count = 0;
    bool possible = true;
    for (int i = 0; i < n; i++) {
        flip ^= end[i];
        if ((a[i] ^ flip) == 0) {
            if (i + k > n) {
                possible = false;
                break;
            }
            flip ^= 1;
            end[i + k] ^= 1;
            count++;
        }
    }
    cout << (possible ? count : -1) << "\n";

    return 0;
}

